from collections import Counter

def transform(grid):
    H,W=len(grid),len(grid[0])
    F=Counter(v for r in grid for v in r).most_common(1)[0][0]
    lr=[i for i in range(H) if sum(1 for v in grid[i] if v!=F)<W*0.5]
    lc=[j for j in range(W) if sum(1 for i in range(H) if grid[i][j]!=F)<H*0.5]
    L=Counter(grid[i][j] for i in lr for j in lc).most_common(1)[0][0]  # line color
    # special points at intersections
    pts={}
    for a,i in enumerate(lr):
        for b,j in enumerate(lc):
            v=grid[i][j]
            if v!=L: pts.setdefault(v,[]).append((a,b))
    # connected components per color via same line-row/col adjacency (consecutive lines)
    def comps(pl):
        pl=set(pl); out=[]
        while pl:
            p=pl.pop(); st=[p]; comp={p}
            while st:
                a,b=st.pop()
                for q in list(pl):
                    x,y=q
                    if (x==a and abs(y-b)==1) or (y==b and abs(x-a)==1):
                        pl.remove(q); st.append(q); comp.add(q)
            out.append(comp)
        return out
    marks={}  # (band_r, band_c) -> color
    for c,pl in pts.items():
        for comp in comps(pl):
            rs=[a for a,b in comp]; cs=[b for a,b in comp]
            r1,r2,c1,c2=min(rs),max(rs),min(cs),max(cs)
            if r2>r1 and c2>c1:
                for i in range(r1,r2):
                    for j in range(c1,c2):
                        marks[(i,j)]=c
            else:
                # degenerate: single line row or col -> take adjacent band toward grid edge/above-left
                if r2==r1 and c2>c1:
                    i=max(r1-1,0)
                    for j in range(c1,c2): marks[(i,j)]=c
                elif c2==c1 and r2>r1:
                    j=max(c1-1,0)
                    for i in range(r1,r2): marks[(i,j)]=c
    if not marks: return [[F]]
    rs=[k[0] for k in marks]; cs=[k[1] for k in marks]
    r1,r2,c1,c2=min(rs),max(rs),min(cs),max(cs)
    return [[marks.get((i,j),F) for j in range(c1,c2+1)] for i in range(r1,r2+1)]

